input, select, textarea, button, #main .button {
	font-family:inherit;
}

button {
	cursor:pointer;
}

body:before {
	content: none !important;
}

a:hover {
	text-decoration: none;
}

.entry-title a,
.post-entry-title a {
	text-decoration: none;
}

.icon:before {
    font-size: 14px;
    margin-right: 5px;
}

a,
.icon:before {
	text-decoration:none;
	outline:none;
	color:#b83806;
}

.skills li .progress {
	background-color:#b83806;
}

a img{
	outline:none;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="url"]:focus,
input[type="password"]:focus,
input[type="search"]:focus,
input[type="number"]:focus,
input[type="tel"]:focus,
input[type="range"]:focus,
input[type="date"]:focus,
input[type="month"]:focus,
input[type="week"]:focus,
input[type="time"]:focus,
input[type="datetime"]:focus,
input[type="datetime-local"]:focus,
input[type="color"]:focus,
textarea:focus {
  border-color: #000;
  outline: solid rgba(0, 115, 170, 0.15);
  outline-offset: -4px;
}

.button:focus,
button:focus,
input[type="button"]:focus,
input[type="reset"]:focus,
input[type="submit"]:focus {
  outline: dotted;
  outline-offset: -4px;
}

p {
	padding:3px 0 3px 0;
	margin:0;
}

img {
	border:0;
	outline:0;
}

.lb-prev,
.lb-next {
	transition:none !important;
}

select {
	background-color: white;
	border: 1px solid #CCC;
	padding: 8px 3px;
	border-radius: 3px;
}

.quantity input[type="number"] {
    background-color: white;
    border: 1px solid #CCC;
    border-radius: 3px;
    font-size: 16px;
    margin-top: 5px;
}

#main-content-wrapper {
	min-height:100px;
	margin-top: 35px !important;
}

#home-content-wrapper img,
#main-content-wrapper img,
#footer-main img {
	max-width:100%;
	height:auto;
}

#home-content-wrapper a:hover img,
#main-content-wrapper a:hover img:not(.slider-img),
#footer-main a:hover img:not(.slider-img) {
	opacity:0.9;
}

article,
.recent-posts-slider-after-content {
	line-height:1.5;
}


h1, h2, h3, h4, h5, h6, .product-title{
	font-weight:400;
	margin:0;
	font-family: 'Raleway', sans-serif;
}
	
h1 {
	font-size:28px;
	padding:10px 0 3px 0;
}

h2, .product-title {
	font-size:22px;
	padding:5px 0 0 0;
}

h3 {
	font-size:20px;
	padding:8px 0 5px 0;
}

h4 {
	font-size:18px;
	padding:2px 0 1px 0;
}

h5 {
	font-size:16px;
	padding:2px 0 1px 0;
}

h6 {
	font-size:16px;
	padding:2px 0 1px 0;
}

table {
    border-collapse: collapse;
}



td, th {
	padding:10px;
}

#wp-calendar,
#wp-calendar th,
#wp-calendar td {
	border:none;
}

#wp-calendar td,
#wp-calendar th {
	padding:0;
}


embed,
object,
video {
	margin-bottom: 24px;
	max-width: 100%;
}

video {
    width: 100% !important;
    height: auto !important;
}

.vimeo-wrapper {
    position: relative;
    padding-bottom: 56.25%;
  	height: 0;
}

.vimeo-wrapper iframe {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
}

iframe {
    max-width: 100%;
}

p > embed,
p > iframe,
p > object,
span > embed,
span > iframe,
span > object {
	margin-bottom: 0;
}


.custom-logo-link img {
	margin-right:10px;
	max-width:100%;
	height:auto;
}

#header-logo strong {
	font-weight:normal;
}

#sidebar select{
	max-width:95%;
}

dt.gallery-icon:before {
	content:'';
	display: none;
}


#footer-bottom-widget-area {
	margin-top:10px;
}

#footer-bottom-area {
	clear:both;
	padding:40px 2%;
	background-color:#292929;
	font-size:14px;
}

#footer-bottom-area,
#footer-bottom-area h1,
#footer-bottom-area h2,
#footer-bottom-area h3 {
	color:#575757;
}

#footer-bottom-area a {
	color:#555555;
}

#footer-bottom-area a:hover {
	color:#747474;
}

#header-logo h1 {
	padding:0;
	line-height:1;
}

#navmain li {
	padding:0;
}

ul > li:not(.wp-social-link) {
	padding:3px 0;
	margin:0;
	list-style-type:none;
}

article ul li {
	list-style-type: circle !important;
}

ol > li {
	padding:3px 0;
	margin:0;
}

article ol {
	padding:0 0 0 30px;
}

article ul {
	padding:0 0 0 15px;
}

ul, ol {
	padding:0;
}


.widget > ul,
.col > ul,
#sidebar > ul {
	padding-left:0;
}

#site-identity h1 {
	-webkit-transition: font-size .5s ease, opacity .4s ease;
	-o-transition: font-size .5s ease, opacity .4s ease;
	transition: font-size .5s ease, opacity .4s ease;
	font-weight:bold;
	font-size: 24px;
}

article {
    max-width:100%;
}

article,
aside {
	-ms-word-wrap: break-word;
	word-wrap: break-word;
}

/* main content */
#main-content,
#main-content-full,
#main {
	padding:10px 0 0 0;
}

#main-content > article:first-of-type h1 {
	margin-top:0;
	padding-top:0;
}

#main-content-full {
	margin:0 0 20px 2%;
	width:96%;
}

/* sidebar */
#sidebar {
	overflow:hidden;
	padding:10px 0 0 0;
}



#sidebar > ul {
	margin-left:3px;
}

#sidebar > ul:not(.social-widget):not(.ui-tabs-nav) li {
    margin-bottom:10px;
    width:85%;
}

#sidebar .teammember-social-icons li {
    border-bottom:none !important;
    margin-bottom:0 !important;
    width:auto !important;
}

#sidebar > ul li:last-of-type {
	border:none !important;
}

#sidebar .widget {
	margin-bottom:5px;
    clear: both;
}

#infoTxt {
	padding:10px 0 10px 0;
}



article,
.additional-content {
	clear:both;
}

.separator {
	height:1px;
	margin:20px 1% 10px 0;
}

#footer-menu ul,
#footer-menu li {
	display:inline;
	padding:0;
	margin:0;
}

#footer-menu li {
	margin-right:4px;
}

#footer-menu li a {
	display:inline-block;
	line-height:1.7;
	border-bottom: 1px dotted;
}

#footer-menu li:after {
	content: '/';
	margin-left:7px;
}

#footer-menu li:last-of-type:after {
	content: '';
}

#footer-menu li a:hover {
	border-bottom-style: solid;
}

#footer-main {
	clear:both;
	background-color:#333333;
	color:#CCCCCC;
	margin:20px 0 0 0;
	padding:80px 2% 80px 2%;
	font-size:14px;
}

#footer-main a {
	color:#BBBBBB;
}

#footer-main a:hover {
	color:#999999;
}

#footer-main ul:not(.social-widget):not(.ui-tabs-nav):not(.footer-social-widget):not(.instagram-pics) li {
    border-bottom:1px solid #333;
    margin-bottom:10px;
    padding-bottom:10px;
    width:85%;
}

#footer-menu ul li,
#footer-main ul li:last-of-type,
#footer-main ul ul li {
	border:none !important;
	padding-bottom:0 !important;
}

.footer-social-widget li {
	display:inline;
}

#footer-main input[type="text"] {
	width:130px;
	background-color:#fff;
}

.footer-social-widget a {
	display:inline-block;
	width:20px;
	height:20px;
	line-height:20px;
	text-align:center;
}

.footer-social-widget a:hover {
	text-decoration:none !important;
	-webkit-transform:rotate(-20deg);
	-moz-transform: rotate(-20deg);
	-o-transform: rotate(-20deg);
	-ms-transform: rotate(-20deg);
	transform: rotate(-20deg);
}

.footer-social-widget a:before {
	font-size:14px;
}

.footer-social-widget li {
	margin-right:5px;
}

#footer-phone-and-email {
	float:right;
	clear:both;
	margin-top:10px;
}

#footer-phone-and-email #footer-phone,
#footer-phone-and-email #footer-email {
	display:inline-block;
}

#footer-phone-and-email #footer-phone {
	margin-right:10px;
}

#footer-main .post-date {
	margin:0 0 5px 0;
}



.col > ul {
	margin-left:3px;
}

.col li {
	margin-bottom:5px;
}

.col1a {
	float:none;
	width:96%;
	margin:5px 0 5px 0;
}

#footer-bottom {
	padding:20px 0 0 0;
	clear:both;
	text-align:center;
}

#footer-bottom .footer-title,
#footer-main h2 {
	float:none;
	border-bottom:none;
	margin-bottom:5px;
}

#footer-bottom #footer-main h2:after {
	display: block;
	content: ' ';
}

#footer-main h2:after {
	display:block;
	content: ' ';
}

.footer-after-title,
#footer-main h2:after {
	display:none;
}

#footer-bottom-widget-area .footer-title,
#footer-main h2 {
	margin-bottom:10px;
}

#fsocial {
	float:right;
