/* Circle Progress */
.position {
  float: left;
  margin: 20px;
}

.circle-progress-bar {
  position: relative;
  height: 200px;
  width: 200px;
}

.circle-progress-bar div {
  position: absolute;
  height: 200px;
  width: 200px;
  border-radius: 50%;
}

.circle-progress-bar div span {
  position: absolute;
  font-family: Arial;
  font-size: 25px;
  line-height: 175px;
  height: 175px;
  width: 175px;
  left: 12.5px;
  top: 12.5px;
  text-align: center;
  border-radius: 50%;
  background-color: white;
}

.circle-progress-bar .background { background-color: #b3cef6; }

.circle-progress-bar .rotate {
  clip: rect(0 100px 200px 0);
  background-color: #4b86db;
}

.circle-progress-bar .left {
  clip: rect(0 100px 200px 0);
  opacity: 1;
  background-color: #b3cef6;
}

.circle-progress-bar .right {
  clip: rect(0 100px 200px 0);
  transform: rotate(180deg);
  opacity: 0;
  background-color: #4b86db;
}
 @keyframes 
toggle {  0% {
 opacity: 0;
